 <body>
  <!-- DEWAHOKI CONSTELLATION START (blok mandiri — untuk batalkan, cabut dari sini) -->
  <canvas id="raya-constellation" aria-hidden="true"></canvas>
  <style>
  #wrap{position:relative;z-index:1;background:transparent!important}
  #raya-constellation{position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}
  </style>
  <script>
  (function(){
    if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;
    var cv=document.getElementById('raya-constellation'),ctx=cv.getContext('2d');
    var W,H,pts=[],mouse={x:-999,y:-999};
    function size(){
      W=cv.width=window.innerWidth;H=cv.height=window.innerHeight;
      var n=Math.min(110,Math.floor(W*H/15000));
      pts=[];
      for(var i=0;i<n;i++)pts.push({
        x:Math.random()*W,y:Math.random()*H,
        vx:(Math.random()-.5)*.45,vy:(Math.random()-.5)*.45,
        r:Math.random()*1.6+.8
      });
    }
    size();
    window.addEventListener('resize',size);
    window.addEventListener('mousemove',function(e){mouse.x=e.clientX;mouse.y=e.clientY;});
    window.addEventListener('mouseout',function(){mouse.x=-999;mouse.y=-999;});
    var DIST=130;
    function loop(){
      ctx.clearRect(0,0,W,H);
      for(var i=0;i<pts.length;i++){
        var p=pts[i];
        p.x+=p.vx;p.y+=p.vy;
        if(p.x<0||p.x>W)p.vx*=-1;
        if(p.y<0||p.y>H)p.vy*=-1;
        ctx.beginPath();
        ctx.fillStyle='rgba(255,209,92,.85)';
        ctx.arc(p.x,p.y,p.r,0,6.2832);ctx.fill();
        for(var j=i+1;j<pts.length;j++){
          var q=pts[j],dx=p.x-q.x,dy=p.y-q.y,d=Math.sqrt(dx*dx+dy*dy);
          if(d<DIST){
            ctx.strokeStyle='rgba(224,167,43,'+(1-d/DIST)*.35+')';
            ctx.lineWidth=1;
            ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();
          }
        }
        var mdx=p.x-mouse.x,mdy=p.y-mouse.y,md=Math.sqrt(mdx*mdx+mdy*mdy);
        if(md<170){
          ctx.strokeStyle='rgba(255,209,92,'+(1-md/170)*.5+')';
          ctx.lineWidth=1;
          ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(mouse.x,mouse.y);ctx.stroke();
        }
      }
      requestAnimationFrame(loop);
    }
    loop();
  })();
  </script>
  <!-- DEWAHOKI CONSTELLATION END (cabut sampai sini) -->
