       Perpaduan Biru: navy · deep blue · electric · sky/cyan
       ============================================================= */

    .container {
        max-width: 1100px;
        margin: 0 auto;
        background: linear-gradient(160deg, #e50914 0%, #e50914 55%, #e50914 100%);
        border-radius: 28px;
        padding: 50px 40px;
        position: relative;
        overflow: hidden;
        box-shadow:
            0 40px 80px -25px rgba(0, 0, 0, 0.7),
            0 0 0 1px rgba(0, 0, 0, 0.25),
            inset 0 1px 0 rgba(0, 0, 0, 0.12);
    }
    .container::before {
        content: '';
        position: absolute;
